<?php $drawerItems=\App\Models\ShopCart::items();$drawerTotal=(int)array_sum(array_column($drawerItems,'price'));?><div class="cart-overlay" id="cartOverlay" hidden></div><aside class="cart-drawer" id="cartDrawer" data-csrf="<?=csrf()?>" aria-hidden="true" aria-labelledby="cartDrawerTitle"><header><div><small>TU SELECCIÓN</small><h2 id="cartDrawerTitle">CARRITO <span id="drawerCount"><?=count($drawerItems)?></span></h2></div><button type="button" id="cartClose" aria-label="Cerrar carrito">×</button></header><div class="drawer-items" id="drawerItems"><?php foreach($drawerItems as $item):?><article data-key="<?=htmlspecialchars($item['key'])?>"><img src="<?=preview_url(['id'=>$item['cover_id']??$item['photo_id'],'preview_path'=>$item['preview_path']])?>" alt=""><div><small><?=htmlspecialchars($item['event_name'])?></small><b><?=htmlspecialchars($item['title'])?></b><span><?=$item['type']==='set'?($item['photos_count'].' fotografías · Set completo'):'Fotografía individual'?></span><strong><?=money($item['price'])?></strong></div><button class="drawer-remove" data-key="<?=htmlspecialchars($item['key'])?>" type="button">ELIMINAR</button></article><?php endforeach;?></div><div class="drawer-empty" id="drawerEmpty" <?=$drawerItems?'hidden':''?>><b>TU CARRITO ESTÁ VACÍO</b><p>Agrega fotografías o sets para comenzar.</p></div><footer><div><span>TOTAL</span><strong id="drawerTotal"><?=money($drawerTotal)?></strong></div><a id="drawerCheckout" class="<?=$drawerItems?'':'is-disabled'?>" href="<?=url('checkout')?>">FINALIZAR COMPRA →</a><a href="<?=url('carrito')?>">VER CARRITO COMPLETO</a><small>Pago seguro mediante Flow · Descarga digital protegida</small></footer></aside>
